function omoDecisionUiT(string $key, array $variables = []): string
{
    static $bundles = [];
    $sourceLang = omoDecisionUiSourceLang();
    $locale = omoGetTranslationLocale();
    $bundle = $bundles[$locale] ??= loadTranslationBundle('omo_decision_ui', $locale, $sourceLang);
    return t($key, $variables, $bundle, $sourceLang);
}
